13	static void bk7258_gpio_uart0(unsigned int pin)
14	{
15	  uint32_t regval;
16	
17	  /* GPIO11 uses peripheral function slot 0 for UART0 TX.  The per-pin GPIO
18	   * control enables the second function, disables GPIO ownership and keeps
19	   * the vendor's pull-up setting. */
20	
21	  regval  = getreg32(BK7258_GPIO_CFG(pin));
22	  regval &= ~(UINT32_C(3) << 2);
23	  regval |=  (UINT32_C(2) << 2);
24	  regval &= ~(UINT32_C(3) << 4);
25	  regval |=  (UINT32_C(3) << 4);
26	  regval |=  (UINT32_C(1) << 6);
27	  putreg32(regval, BK7258_GPIO_CFG(pin));
28	
29	  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
30	  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
31	  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
32	}
33	
34	void bk7258_gpio_uart0_tx(void)
35	{
36	  bk7258_gpio_uart0(BK7258_GPIO11);
37	}
38	
39	void bk7258_gpio_uart0_rx(void)
40	{
41	  bk7258_gpio_uart0(10);
42	}
