44	/****************************************************************************
45	 * Name: bk7258_gpio_select_func
46	 *
47	 * Description:
48	 *   Route the pin to its plain GPIO function (peripheral mux field = 0).
49	 *
50	 ****************************************************************************/
51	
52	static void bk7258_gpio_select_func(unsigned int pin)
53	{
54	  uint32_t regval;
55	  uint32_t reg  = BK7258_SYS_GPIO_FUNC(pin);
56	  uint32_t mask = BK7258_GPIO_FUNC_MASK(pin);
57	
58	  regval  = getreg32(reg);
59	  regval &= ~mask;
60	  putreg32(regval, reg);
61	}
62	
63	/****************************************************************************
64	 * Name: bk7258_gpio_periph
65	 *
66	 * Description:
67	 *   Route the pin to a peripheral (second) function selected by the 4-bit
68	 *   per-pin mux field (see the Armino SDK gpio_map.h table, e.g. option 0
69	 *   on GPIO2/4 is the SPI1 SCK/MOSI).  The per-pin GPIO control is set to
70	 *   I/O-disable plus second-function so the peripheral owns the pad.
71	 *
72	 ****************************************************************************/
73	
74	void bk7258_gpio_periph(unsigned int pin, unsigned int func)
75	{
76	  uint32_t regval;
77	
78	  regval  = getreg32(BK7258_GPIO_CFG(pin));
79	  regval &= ~(UINT32_C(3) << 2);        /* clear IO mode */
80	  regval |=  (UINT32_C(2) << 2);        /* I/O disable: peripheral drives */
81	  regval &= ~(UINT32_C(3) << 4);        /* clear pull */
82	  regval |=  (UINT32_C(1) << 6);        /* second function enable */
83	  regval &= ~BK7258_GPIO_CFG_OUTPUT_EN;
84	  regval &= ~BK7258_GPIO_CFG_INPUT_EN;
85	  putreg32(regval, BK7258_GPIO_CFG(pin));
86	
87	  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
88	  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
89	  regval |=  (func & UINT32_C(0xf)) << (((uint32_t)(pin) & 7) << 2);
90	  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
91	}
92	
93	/****************************************************************************
94	 * Name: bk7258_gpio_config_output
95	 *
96	 * Description:
97	 *   Configure the GPIO pin as a push-pull output with no pull resistor.
98	 *
99	 ****************************************************************************/
100	
101	void bk7258_gpio_config_output(unsigned int pin)
102	{
103	  uint32_t regval;
104	
105	  bk7258_gpio_select_func(pin);
106	
107	  regval  = getreg32(BK7258_GPIO_CFG(pin));
108	  regval &= ~BK7258_GPIO_CFG_MODE_MASK;
109	  regval |= BK7258_GPIO_CFG_MODE_OUTPUT;
110	  regval &= ~BK7258_GPIO_CFG_PULL_MASK;
111	  regval &= ~BK7258_GPIO_CFG_SECOND_FUNC;
112	  regval &= ~BK7258_GPIO_CFG_OUTPUT_EN;  /* LOW active: 0 = output enabled */
113	  regval &= ~BK7258_GPIO_CFG_INPUT_EN;   /* disable input path */
114	  putreg32(regval, BK7258_GPIO_CFG(pin));
115	}
116	
117	/****************************************************************************
118	 * Name: bk7258_gpio_config_input
119	 *
120	 * Description:
121	 *   Configure the GPIO pin as an input with optional pull-up.
122	 *
123	 ****************************************************************************/
124	
125	void bk7258_gpio_config_input(unsigned int pin)
126	{
127	  uint32_t regval;
128	
129	  bk7258_gpio_select_func(pin);
130	
131	  regval  = getreg32(BK7258_GPIO_CFG(pin));
132	  regval &= ~BK7258_GPIO_CFG_MODE_MASK;
133	  regval |= BK7258_GPIO_CFG_MODE_INPUT;
134	  regval &= ~BK7258_GPIO_CFG_PULL_MASK;
135	  regval |= BK7258_GPIO_CFG_PULL_UP;
136	  regval &= ~BK7258_GPIO_CFG_SECOND_FUNC;
137	  regval |= BK7258_GPIO_CFG_OUTPUT_EN;  /* disable output path */
138	  regval |= BK7258_GPIO_CFG_INPUT_EN;   /* HIGH active: 1 = input enabled */
139	  putreg32(regval, BK7258_GPIO_CFG(pin));
140	}
