142	/****************************************************************************
143	 * Name: bk7258_gpio_write
144	 *
145	 * Description:
146	 *   Drive a GPIO output pin to the requested level.
147	 *
148	 ****************************************************************************/
149	
150	void bk7258_gpio_write(unsigned int pin, bool high)
151	{
152	  uint32_t regval;
153	
154	  regval  = getreg32(BK7258_GPIO_CFG(pin));
155	  if (high)
156	    {
157	      regval |= BK7258_GPIO_CFG_DATA;
158	    }
159	  else
160	    {
161	      regval &= ~BK7258_GPIO_CFG_DATA;
162	    }
163	
164	  putreg32(regval, BK7258_GPIO_CFG(pin));
165	}
166	
167	/****************************************************************************
168	 * Name: bk7258_gpio_read
169	 *
170	 * Description:
171	 *   Sample the level of a GPIO pin configured as an input.
172	 *
173	 ****************************************************************************/
174	
175	bool bk7258_gpio_read(unsigned int pin)
176	{
177	  return (getreg32(BK7258_GPIO_CFG(pin)) & BK7258_GPIO_CFG_DATA) != 0;
178	}
