1	/****************************************************************************
2	 * chips/bk7258/bk7258_irq.c
3	 ****************************************************************************/
4	
5	#include <nuttx/config.h>
6	
7	#include <errno.h>
8	#include <stdint.h>
9	
10	#include <nuttx/arch.h>
11	#include <nuttx/irq.h>
12	
13	#include "arm_internal.h"
14	#include "nvic.h"
15	#include "bk7258_internal.h"
16	
17	extern const void *const _vectors[];
18	
19	static int bk7258_irqinfo(int irq, uintptr_t *regaddr, uint32_t *bit,
20	                          uintptr_t offset)
21	{
22	  int external;
23	
24	  if (irq >= NVIC_IRQ_FIRST && irq < NR_IRQS)
25	    {
26	      external = irq - NVIC_IRQ_FIRST;
27	      *regaddr = NVIC_IRQ_ENABLE(external) + offset;
28	      *bit = UINT32_C(1) << (external & 31);
29	      return OK;
30	    }
31	
32	  if (irq == NVIC_IRQ_SYSTICK)
33	    {
34	      *regaddr = NVIC_SYSTICK_CTRL;
35	      *bit = NVIC_SYSTICK_CTRL_ENABLE;
36	      return OK;
37	    }
38	
39	  return -EINVAL;
40	}
41	
42	int up_prioritize_irq(int irq, int priority)
43	{
44	  uintptr_t regaddr;
45	  uint32_t regval;
46	  int shift;
47	
48	  if (irq < 0 || irq >= NR_IRQS || priority < 0 || priority > 0xff)
49	    {
50	      return -EINVAL;
51	    }
52	
53	  if (irq < NVIC_IRQ_FIRST)
54	    {
55	      if (irq < 4)
56	        {
57	          return -EINVAL;
58	        }
59	
60	      regaddr = NVIC_SYSH_PRIORITY(irq);
61	      irq -= 4;
62	    }
63	  else
64	    {
65	      irq -= NVIC_IRQ_FIRST;
66	      regaddr = NVIC_IRQ_PRIORITY(irq);
67	    }
68	
69	  shift = (irq & 3) << 3;
70	  regval = getreg32(regaddr);
71	  regval &= ~(UINT32_C(0xff) << shift);
72	  regval |= (uint32_t)priority << shift;
73	  putreg32(regval, regaddr);
74	  return OK;
75	}
76	
77	void up_disable_irq(int irq)
78	{
79	  uintptr_t regaddr;
80	  uint32_t bit;
81	
82	  if (bk7258_irqinfo(irq, &regaddr, &bit,
83	                      NVIC_IRQ0_31_CLEAR - NVIC_IRQ0_31_ENABLE) == OK)
84	    {
85	      if (irq >= NVIC_IRQ_FIRST)
86	        {
87	          putreg32(bit, regaddr);
88	        }
89	      else
90	        {
91	          modifyreg32(regaddr, bit, 0);
92	        }
93	    }
94	}
95	
96	void up_enable_irq(int irq)
97	{
98	  uintptr_t regaddr;
99	  uint32_t bit;
100	
101	  if (bk7258_irqinfo(irq, &regaddr, &bit, 0) == OK)
102	    {
103	      if (irq >= NVIC_IRQ_FIRST)
104	        {
105	          putreg32(bit, regaddr);
106	        }
107	      else
108	        {
109	          modifyreg32(regaddr, 0, bit);
110	        }
111	    }
112	}
113	
114	void arm_ack_irq(int irq)
115	{
116	  (void)irq;
117	}
118	
119	void up_irqinitialize(void)
120	{
121	  int irq;
122	
123	  for (irq = 0; irq < NR_IRQS - NVIC_IRQ_FIRST; irq += 32)
124	    {
125	      putreg32(UINT32_MAX, NVIC_IRQ_CLEAR(irq));
126	      putreg32(UINT32_MAX, NVIC_IRQ_CLRPEND(irq));
127	    }
128	
129	  putreg32((uintptr_t)_vectors, NVIC_VECTAB);
130	  irq_attach(NVIC_IRQ_SVCALL, arm_svcall, NULL);
131	  irq_attach(NVIC_IRQ_HARDFAULT, arm_hardfault, NULL);
132	  irq_attach(NVIC_IRQ_MEMFAULT, arm_memfault, NULL);
133	  irq_attach(NVIC_IRQ_BUSFAULT, arm_busfault, NULL);
134	  irq_attach(NVIC_IRQ_USAGEFAULT, arm_usagefault, NULL);
135	  irq_attach(NVIC_IRQ_SECUREFAULT, arm_securefault, NULL);
136	
137	  modifyreg32(NVIC_SYSHCON, 0,
138	              NVIC_SYSHCON_MEMFAULTENA | NVIC_SYSHCON_BUSFAULTENA |
139	              NVIC_SYSHCON_USGFAULTENA | NVIC_SYSHCON_SECUREFAULTENA);
140	  up_prioritize_irq(NVIC_IRQ_PENDSV, NVIC_SYSH_PRIORITY_MIN);
141	
142	  /* SVC drives NuttX thread-mode context switches. It must remain above the
143	   * BASEPRI level used to mask normal interrupts in critical sections. */
144	
145	  up_prioritize_irq(NVIC_IRQ_SVCALL, NVIC_SYSH_SVCALL_PRIORITY);
146	  up_irq_enable();
147	}
148

