 * WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or
 * implied.  See the License for the specific language governing
 * permissions and limitations under the License.
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <errno.h>
#include <stdint.h>

#include <nuttx/irq.h>

#include "arm_internal.h"
#include "bk7258_internal.h"
#include "include/bk7258_gpio.h"
#include "include/bk7258_memorymap.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* GPIO interrupt registers - based on BK7258 Armino SDK gpio_reg.h
 * GPIO_INT_BASE = 0x44000600 (AON domain)
 *
 * Offset  Register
 * 0x00    GPIO_INT_ENABLE    - per-pin interrupt enable
 * 0x04    GPIO_INT_TYPE      - edge(1) or level(0) trigger
 * 0x08    GPIO_INT_POLARITY  - rising/high(1) or falling/low(0)
 * 0x0C    GPIO_INT_STATUS    - pending status (write 1 to clear)
 * 0x10    GPIO_INT_RAW       - raw status before masking
 */

#define BK7258_GPIO_INT_BASE     UINT32_C(0x44000600)
#define BK7258_GPIO_INT_ENABLE   (BK7258_GPIO_INT_BASE + 0x00)
#define BK7258_GPIO_INT_TYPE     (BK7258_GPIO_INT_BASE + 0x04)
#define BK7258_GPIO_INT_POLARITY (BK7258_GPIO_INT_BASE + 0x08)
#define BK7258_GPIO_INT_STATUS   (BK7258_GPIO_INT_BASE + 0x0C)
#define BK7258_GPIO_INT_RAW      (BK7258_GPIO_INT_BASE + 0x10)

/* IRQ handler table size */

#define GPIO_IRQ_SLOTS           32  /* Support GPIO0-31 for IRQ */

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* Per-pin IRQ handler storage */

struct bk7258_gpio_irq_s
{
  xcpt_t handler;
  void  *arg;
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct bk7258_gpio_irq_s g_gpio_irqs[GPIO_IRQ_SLOTS];

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static void bk7258_gpio_select_func(unsigned int pin)
{
  uint32_t regval;
  uint32_t reg  = BK7258_SYS_GPIO_FUNC(pin);
  uint32_t mask = BK7258_GPIO_FUNC_MASK(pin);

  regval  = getreg32(reg);
  regval &= ~mask;
  putreg32(regval, reg);
}

static inline bool bk7258_gpio_valid(unsigned int pin)
{
  return pin < BK7258_GPIO_MAX_PIN;
}

static inline bool bk7258_gpio_irq_valid(unsigned int pin)
{
  return pin < GPIO_IRQ_SLOTS;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_gpio_config_input
 ****************************************************************************/

int bk7258_gpio_config_input(unsigned int pin,
                             enum bk7258_gpio_pull_e pull)
{
  uint32_t regval;

  if (!bk7258_gpio_valid(pin))
    {
      return -EINVAL;
    }

  bk7258_gpio_select_func(pin);

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~BK7258_GPIO_CFG_MODE_MASK;
  regval |= BK7258_GPIO_CFG_MODE_INPUT;
  regval &= ~BK7258_GPIO_CFG_PULL_MASK;

  switch (pull)
    {
      case BK7258_GPIO_PULL_UP:
        regval |= BK7258_GPIO_CFG_PULL_UP;
        break;
      case BK7258_GPIO_PULL_DOWN:
        regval |= (UINT32_C(1) << 4);  /* Pull-down encoding */
        break;
      default:
        break;
    }

  regval &= ~BK7258_GPIO_CFG_SECOND_FUNC;
  regval |= BK7258_GPIO_CFG_OUTPUT_EN;  /* disable output path */
  regval |= BK7258_GPIO_CFG_INPUT_EN;   /* HIGH active: 1 = input enabled */
  putreg32(regval, BK7258_GPIO_CFG(pin));

  return OK;
}

/****************************************************************************
 * Name: bk7258_gpio_config_output
 ****************************************************************************/

int bk7258_gpio_config_output(unsigned int pin, bool initial)
{
  uint32_t regval;

  if (!bk7258_gpio_valid(pin))
    {
      return -EINVAL;
    }

  /* Set initial value before switching to output to avoid glitch */

  bk7258_gpio_write(pin, initial);

  bk7258_gpio_select_func(pin);

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~BK7258_GPIO_CFG_MODE_MASK;
  regval |= BK7258_GPIO_CFG_MODE_OUTPUT;
  regval &= ~BK7258_GPIO_CFG_PULL_MASK;
  regval &= ~BK7258_GPIO_CFG_SECOND_FUNC;
  regval &= ~BK7258_GPIO_CFG_OUTPUT_EN;  /* LOW active: 0 = output enabled */
  regval &= ~BK7258_GPIO_CFG_INPUT_EN;   /* disable input path */
  putreg32(regval, BK7258_GPIO_CFG(pin));

  return OK;
}

/****************************************************************************
 * Name: bk7258_gpio_write
 ****************************************************************************/

void bk7258_gpio_write(unsigned int pin, bool high)
{
  uint32_t regval;

  if (!bk7258_gpio_valid(pin))
    {
      return;
    }

  regval = getreg32(BK7258_GPIO_CFG(pin));
  if (high)
    {
      regval |= BK7258_GPIO_CFG_DATA;
    }
  else
    {
      regval &= ~BK7258_GPIO_CFG_DATA;
    }

  putreg32(regval, BK7258_GPIO_CFG(pin));
}

/****************************************************************************
 * Name: bk7258_gpio_read
 ****************************************************************************/

bool bk7258_gpio_read(unsigned int pin)
{
  if (!bk7258_gpio_valid(pin))
    {
      return false;
    }

  return (getreg32(BK7258_GPIO_CFG(pin)) & BK7258_GPIO_CFG_DATA) != 0;
}

/****************************************************************************
 * Name: bk7258_gpio_irq_attach
 ****************************************************************************/

int bk7258_gpio_irq_attach(unsigned int pin, xcpt_t handler, void *arg)
{
  if (!bk7258_gpio_irq_valid(pin))
    {
      return -EINVAL;
    }

  g_gpio_irqs[pin].handler = handler;
  g_gpio_irqs[pin].arg     = arg;

  return OK;
}

/****************************************************************************
 * Name: bk7258_gpio_irq_enable
 ****************************************************************************/

int bk7258_gpio_irq_enable(unsigned int pin, bool rising, bool falling)
{
  uint32_t bit;

  if (!bk7258_gpio_irq_valid(pin))
    {
      return -EINVAL;
    }

  bit = UINT32_C(1) << pin;

  /* Configure edge trigger */

  modifyreg32(BK7258_GPIO_INT_TYPE, 0, bit);  /* edge trigger */

  /* Configure polarity: rising=1, falling=0
   * For dual-edge, we use rising as default and handle falling in ISR
   * by re-reading the pin level */

  if (rising)
    {
      modifyreg32(BK7258_GPIO_INT_POLARITY, 0, bit);
    }
  else
    {
      modifyreg32(BK7258_GPIO_INT_POLARITY, bit, 0);
    }

  /* Clear any pending interrupt */

  putreg32(bit, BK7258_GPIO_INT_STATUS);

  /* Enable interrupt */

  modifyreg32(BK7258_GPIO_INT_ENABLE, 0, bit);

  return OK;
}

/****************************************************************************
 * Name: bk7258_gpio_irq_disable
 ****************************************************************************/

void bk7258_gpio_irq_disable(unsigned int pin)
{
  uint32_t bit;

  if (!bk7258_gpio_irq_valid(pin))
    {
      return;
    }

  bit = UINT32_C(1) << pin;

  /* Disable interrupt */

  modifyreg32(BK7258_GPIO_INT_ENABLE, bit, 0);

  /* Clear any pending interrupt */

  putreg32(bit, BK7258_GPIO_INT_STATUS);
}

/****************************************************************************
 * Name: bk7258_gpio_uart0_tx / bk7258_gpio_uart0_rx
 *
 * Description:
 *   Legacy UART0 pin configuration (kept for backward compatibility).
 *
 ****************************************************************************/

static void bk7258_gpio_uart0(unsigned int pin)
{
  uint32_t regval;

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~(UINT32_C(3) << 2);
  regval |=  (UINT32_C(2) << 2);
  regval &= ~(UINT32_C(3) << 4);
  regval |=  (UINT32_C(3) << 4);
  regval |=  (UINT32_C(1) << 6);
  putreg32(regval, BK7258_GPIO_CFG(pin));

  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
}

void bk7258_gpio_uart0_tx(void)
{
  bk7258_gpio_uart0(BK7258_GPIO11);
}

void bk7258_gpio_uart0_rx(void)
{
  bk7258_gpio_uart0(10);
}

/****************************************************************************
 * Name: bk7258_gpio_periph
 ****************************************************************************/

void bk7258_gpio_periph(unsigned int pin, unsigned int func)
{
  uint32_t regval;

  if (!bk7258_gpio_valid(pin))
    {
      return;
    }

  regval  = getreg32(BK7258_GPIO_CFG(pin));
  regval &= ~(UINT32_C(3) << 2);
  regval |=  (UINT32_C(2) << 2);
  regval &= ~(UINT32_C(3) << 4);
  regval |=  (UINT32_C(1) << 6);
  regval &= ~BK7258_GPIO_CFG_OUTPUT_EN;
  regval &= ~BK7258_GPIO_CFG_INPUT_EN;
  putreg32(regval, BK7258_GPIO_CFG(pin));

  regval  = getreg32(BK7258_SYS_GPIO_FUNC(pin));
  regval &= ~BK7258_GPIO_FUNC_MASK(pin);
  regval |=  (func & UINT32_C(0xf)) << (((uint32_t)(pin) & 7) << 2);
  putreg32(regval, BK7258_SYS_GPIO_FUNC(pin));
}

/****************************************************************************
 * Name: bk7258_gpio_dispatch
 *
 * Description:
 *   GPIO interrupt dispatcher. Called from the IRQ handler to process
 *   pending GPIO interrupts.
 *
 ****************************************************************************/

void bk7258_gpio_dispatch(void)
{
  uint32_t pending;
  int i;

  /* Read and clear all pending interrupts */

  pending = getreg32(BK7258_GPIO_INT_STATUS);
  putreg32(pending, BK7258_GPIO_INT_STATUS);

  /* Dispatch each pending interrupt */

  for (i = 0; i < GPIO_IRQ_SLOTS && pending != 0; i++)
    {
      uint32_t bit = UINT32_C(1) << i;

      if ((pending & bit) != 0)
        {
          pending &= ~bit;

          if (g_gpio_irqs[i].handler != NULL)
            {
              g_gpio_irqs[i].handler(i, g_gpio_irqs[i].arg);
            }
        }
    }
}

