#include <nuttx/clock.h>

#include "bk7258_internal.h"
#include "board.h"

#ifdef CONFIG_AUDIO_BK7258

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int bk7258_devkit_pa_init(FAR void *arg)
{
  int ret;

  (void)arg;

  /* Configure PA pin as output, initially low (PA disabled) */

  ret = bk7258_gpio_config_output(BOARD_AUDIO_PA_PIN, false);
  if (ret < 0)
    {
      syslog(LOG_ERR, "BK7258 PA: failed to configure GPIO%d: %d\n",
             BOARD_AUDIO_PA_PIN, ret);
      return ret;
    }

  syslog(LOG_INFO, "BK7258 PA: initialized GPIO%d (active-%s)\n",
         BOARD_AUDIO_PA_PIN,
         BOARD_AUDIO_PA_ACTIVE_HIGH ? "high" : "low");

  return OK;
}

static void bk7258_devkit_pa_enable(FAR void *arg)
{
  (void)arg;

  /* Pre-enable delay: DAC should be muted during this time */

  nxsig_usleep(BOARD_AUDIO_PA_PRE_ENABLE_MS * 1000);

  /* Drive PA to active level */

#if BOARD_AUDIO_PA_ACTIVE_HIGH
  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, true);
#else
  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, false);
#endif

  /* Post-enable delay: wait for PA to settle */

  nxsig_usleep(BOARD_AUDIO_PA_POST_ENABLE_MS * 1000);

  syslog(LOG_DEBUG, "BK7258 PA: enabled\n");
}

static void bk7258_devkit_pa_disable(FAR void *arg)
{
  (void)arg;

  /* Pre-disable delay: DAC should be muted during this time */

  nxsig_usleep(BOARD_AUDIO_PA_PRE_DISABLE_MS * 1000);

  /* Drive PA to inactive level */

#if BOARD_AUDIO_PA_ACTIVE_HIGH
  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, false);
#else
  bk7258_gpio_write(BOARD_AUDIO_PA_PIN, true);
#endif

  /* Post-disable delay: wait for PA to settle */

  nxsig_usleep(BOARD_AUDIO_PA_POST_DISABLE_MS * 1000);

  syslog(LOG_DEBUG, "BK7258 PA: disabled\n");
}

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct bk7258_audio_pa_ops g_bk7258_devkit_pa_ops =
{
  .init    = bk7258_devkit_pa_init,
  .enable  = bk7258_devkit_pa_enable,
  .disable = bk7258_devkit_pa_disable,
  .arg     = NULL,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

void bk7258_devkit_audio_pa_register(void)
{
  bk7258_audio_pa_register(&g_bk7258_devkit_pa_ops);
}

#endif /* CONFIG_AUDIO_BK7258 */

