#ifdef CONFIG_INPUT_BUTTONS

/****************************************************************************
 * Private Data
 ****************************************************************************/

/* Pin numbers for each button, indexed by BUTTON_KEYx */

static const uint8_t g_button_pins[NUM_BUTTONS] =
{
  BOARD_KEY1_PIN,
  BOARD_KEY2_PIN,
  BOARD_KEY3_PIN,
};

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: board_button_initialize
 *
 * Description:
 *   Initialize all button GPIOs as inputs with internal pull-up.
 *   Buttons are active-low: pressed = low = 1 in bitmask.
 *
 ****************************************************************************/

uint32_t board_button_initialize(void)
{
  int i;
  int ret;

  for (i = 0; i < NUM_BUTTONS; i++)
    {
      ret = bk7258_gpio_config_input(g_button_pins[i],
                                     BK7258_GPIO_PULL_UP);
      if (ret < 0)
        {
          syslog(LOG_ERR, "BK7258 btn: failed to configure GPIO%d: %d\n",
                 g_button_pins[i], ret);
        }
    }

  return NUM_BUTTONS;
}

/****************************************************************************
 * Name: board_buttons
 *
 * Description:
 *   Return the current state of all buttons as a bitmask.
 *   Active-low buttons are inverted: pressed = 1.
 *
 ****************************************************************************/

btn_buttonset_t board_buttons(void)
{
  btn_buttonset_t buttons = 0;
  int i;

  for (i = 0; i < NUM_BUTTONS; i++)
    {
      bool level = bk7258_gpio_read(g_button_pins[i]);

#ifdef BOARD_KEYS_ACTIVE_LOW
      /* Active-low: low level means pressed */

      if (!level)
        {
          buttons |= (1u << i);
        }
#else
      /* Active-high: high level means pressed */

      if (level)
        {
          buttons |= (1u << i);
        }
#endif
    }

  return buttons;
}

/****************************************************************************
 * Name: board_button_irq
 *
 * Description:
 *   Attach/detach an interrupt handler for a specific button.
 *   When handler is non-NULL, enable both rising and falling edges.
 *   When handler is NULL, disable the interrupt.
 *
 ****************************************************************************/

int board_button_irq(int id, xcpt_t irqhandler, void *arg)
{
  int ret;

  if (id < 0 || id >= NUM_BUTTONS)
    {
      return -EINVAL;
    }

  if (irqhandler != NULL)
    {
      /* Attach handler */

      ret = bk7258_gpio_irq_attach(g_button_pins[id], irqhandler, arg);
      if (ret < 0)
        {
          return ret;
        }

      /* Enable both rising and falling edges for press/release detection */

      ret = bk7258_gpio_irq_enable(g_button_pins[id], true, true);
      if (ret < 0)
        {
          return ret;
        }
    }
  else
    {
      /* Disable interrupt and detach handler */

      bk7258_gpio_irq_disable(g_button_pins[id]);
      bk7258_gpio_irq_attach(g_button_pins[id], NULL, NULL);
    }

  return OK;
}

#endif /* CONFIG_INPUT_BUTTONS */

