#include <nuttx/config.h>

#include <errno.h>
#include <fcntl.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>

#include <nuttx/fs/fs.h>
#include <nuttx/irq.h>

#include "bk7258_internal.h"
#include "board.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define BUTTONS_DEV_PATH "/dev/btn0"

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct buttons_dev_s
{
  uint8_t state;  /* Current button state bitmask */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct buttons_dev_s g_buttons_dev;

/* Pin numbers for each button, indexed by BUTTON_KEYx */

static const uint8_t g_button_pins[NUM_BUTTONS] =
{
  BOARD_KEY1_PIN,
  BOARD_KEY2_PIN,
  BOARD_KEY3_PIN,
};

/****************************************************************************
 * Private Function Prototypes
 ****************************************************************************/

static int     buttons_open(FAR struct file *filep);
static int     buttons_close(FAR struct file *filep);
static ssize_t buttons_read(FAR struct file *filep, FAR char *buffer,
                            size_t buflen);
static ssize_t buttons_write(FAR struct file *filep,
                             FAR const char *buffer, size_t buflen);
static int     buttons_ioctl(FAR struct file *filep, int cmd,
                             unsigned long arg);

/****************************************************************************
 * Private Data
 ****************************************************************************/

static const struct file_operations g_buttons_ops =
{
  buttons_open,   /* open */
  buttons_close,  /* close */
  buttons_read,   /* read */
  buttons_write,  /* write */
  NULL,           /* seek */
  buttons_ioctl,  /* ioctl */
  NULL,           /* mmap */
  NULL,           /* truncate */
  NULL,           /* poll */
};

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static uint8_t buttons_read_hw(void)
{
  uint8_t buttons = 0;
  int i;

  for (i = 0; i < NUM_BUTTONS; i++)
    {
      bool level = bk7258_gpio_read(g_button_pins[i]);

#ifdef BOARD_KEYS_ACTIVE_LOW
      /* Active-low: low level means pressed */

      if (!level)
        {
          buttons |= (1u << i);
        }
#else
      /* Active-high: high level means pressed */

      if (level)
        {
          buttons |= (1u << i);
        }
#endif
    }

  return buttons;
}

static int buttons_open(FAR struct file *filep)
{
  return OK;
}

static int buttons_close(FAR struct file *filep)
{
  return OK;
}

static ssize_t buttons_read(FAR struct file *filep, FAR char *buffer,
                            size_t buflen)
{
  if (buflen < 1)
    {
      return -EINVAL;
    }

  /* Read current button state */

  g_buttons_dev.state = buttons_read_hw();
  buffer[0] = g_buttons_dev.state;

  return 1;
}

static ssize_t buttons_write(FAR struct file *filep,
                             FAR const char *buffer, size_t buflen)
{
  /* Write not supported */

  return -ENOSYS;
}

static int buttons_ioctl(FAR struct file *filep, int cmd,
                         unsigned long arg)
{
  /* No custom ioctls for now */

  return -ENOTTY;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bk7258_buttons_initialize
 *
 * Description:
 *   Initialize the button GPIOs and register /dev/btn0.
 *
 ****************************************************************************/

int bk7258_buttons_initialize(void)
{
  int ret;
  int i;

  /* Configure all button GPIOs as inputs with pull-up */

  for (i = 0; i < NUM_BUTTONS; i++)
    {
      ret = bk7258_gpio_config_input(g_button_pins[i],
                                     BK7258_GPIO_PULL_UP);
      if (ret < 0)
        {
          syslog(LOG_ERR, "BK7258 btn: failed to configure GPIO%d: %d\n",
                 g_button_pins[i], ret);
          return ret;
        }
    }

  /* Initialize device state */

  memset(&g_buttons_dev, 0, sizeof(g_buttons_dev));

  /* Register the character device */

  ret = register_driver(BUTTONS_DEV_PATH, &g_buttons_ops, 0666,
                        &g_buttons_dev);
  if (ret < 0)
    {
      syslog(LOG_ERR, "BK7258 btn: failed to register %s: %d\n",
             BUTTONS_DEV_PATH, ret);
      return ret;
    }

  syslog(LOG_INFO, "BK7258: %s registered (KEY1=GPIO%d KEY2=GPIO%d "
         "KEY3=GPIO%d)\n",
         BUTTONS_DEV_PATH,
         BOARD_KEY1_PIN, BOARD_KEY2_PIN, BOARD_KEY3_PIN);

  return OK;
}

